type ConversationScope={accountId:string;chatId:string;topicId:number};
const conversationKey=({accountId,chatId,topicId}:ConversationScope)=>accountId+':'+chatId+':'+topicId;
function mergeSearchResults(previous:Message[],next:Message[]){
  return [...new Map([...previous,...next].map(message=>[message.chatId+':'+message.id,message])).values()];
}
const bytes=(size:number)=>size<1048576?`${Math.ceil(size/1024)} KB`:`${(size/1048576).toFixed(1)} MB`;
function IconButton({label,children,onClick,active=false,disabled=false,className=''}:{label:string;children:ReactNode;onClick():void;active?:boolean;disabled?:boolean;className?:string}){const {t}=useLanguage();return <button className={`icon-button ${active?'is-active':''} ${className}`.trim()} title={t(label)} aria-label={t(label)} onClick={onClick} disabled={disabled}>{children}</button>;}
function ChatTransition(){return <div className="chat-transition" role="status" aria-label="Abriendo conversación"><span className="chat-transition-halo" aria-hidden="true"><Brand/></span></div>;}


function ContactAvatar({contact}:{contact:Contact}){const initials=(contact.name||'C').slice(0,1).toUpperCase();return <span className="contact-avatar">{contact.photo?<MediaView media={contact.photo} auto eager passive fallback={initials}/>:initials}</span>;}
function MenuItem({icon,label,onClick,danger=false}:{icon:ReactNode;label:string;onClick():void;danger?:boolean}){const {t}=useLanguage();return <button className={`menu-item ${danger?'text-danger':''}`} onClick={onClick}>{icon}<span>{t(label)}</span><ChevronRight size={15}/></button>;}
function TranslateMessageOption({message,allowed,translate}:{message:Message;allowed:boolean;translate():void}){
  return useShowMessageTranslation(message,allowed)
    ? <MenuItem icon={<Languages/>} label="Traducir mensaje" onClick={translate}/>
    : null;
}
function UpdatePrompt({update,run,close}:{update:NonNullable<State['update']>;run:Run;close():void}){const notes=update.notes||releaseNotesFor(update.availableVersionCode);const act=(method:string)=>{void run(method).finally(()=>{if(method==='updates.open'||method==='updates.complete')close();});};return <div className="update-notice"><Modal title="Actualización de WRGram" close={close}><p>Google Play ofrece el código {update.availableVersionCode}; estás usando el {update.currentVersionCode}.</p><section className="update-notes"><strong>Novedades</strong><p>{notes||'Google Play no expone las notas de versión a la API de actualización. Abre la ficha para consultar las notas oficiales de esta pista.'}</p></section><UpdateProgress update={update}/><div className="modal-actions"><button className="secondary" onClick={()=>act('updates.open')}>Ver cambios en Google Play</button><button className="primary" disabled={!!update.starting||!!update.downloading||!!update.installing} onClick={()=>act(update.downloaded?'updates.complete':'updates.start')}>{update.downloaded?'Instalar actualización':update.downloading?'Descargando…':update.starting?'Esperando a Play…':'Actualizar ahora'}<ArrowRight size={16}/></button></div><button className="text-button" onClick={close}>Más tarde</button></Modal></div>;}

