  const highlightId=highlight?.chatId===state.active?highlight?.id:'';const [draft,setDraft]=useState('');const [draftEntities,setDraftEntities]=useState<TextEntity[]>([]);const draftEmojis=useRef(new Map<string,TextEntity[]>());const [alphabetic,setAlphabetic]=useState(false);const drafts=useRef(new Map<string,string>());const draftTimers=useRef(new Map<string,ReturnType<typeof setTimeout>>());const field=useRef<HTMLTextAreaElement>(null);const history=useRef<HTMLDivElement>(null);const historyContents=useRef<HTMLDivElement>(null);const followLatest=useRef(true);const activeId=useRef(state.active);const lastAccount=useRef(state.selfId);const pinnedChat=useRef('');const pinnedTopic=useRef(0);const [jump,setJump]=useState(false);const jumpPending=useRef(false);const unreadAnchor=useRef(false);const olderPending=useRef<{scope:string;first?:string;height:number;top:number;started:number;loading:boolean}|undefined>(undefined);const [updateDismissed,setUpdateDismissed]=useState(0),[showUpdate,setShowUpdate]=useState(false);const [recording,setRecording]=useState(false);const [inlineBusy,setInlineBusy]=useState(false);const [forumVersion,setForumVersion]=useState(0);const readFloors=useRef(new Map<string,string>());const readTimer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);
  const [quickChats,setQuickChats]=useState(false);
