  useEffect(()=>{if(!recording)return;setRecording(false);void run('voice.cancel');},[state.active]);
 const active=state.chats.find(chat=>chat.id===state.active);const desktop=state.platform==='desktop';const report=(error:unknown)=>setToast(error instanceof Error?error.message:'No se pudo completar la operación.');const inlineMatch=state.canSend&&state.active!=='0'?/^@([A-Za-z0-9_]{3,32})\s+([\s\S]*)$/.exec(draft.trim()):null;
 const botScope=state.selfId+'|'+state.active+'|'+(state.topic?.id||0);
 const canPublishAsBot=botAccess?.scope===botScope&&botAccess.publish;
