function handleTelegramLinkResult(result:TelegramLinkResult|boolean|undefined){
  if(!result||typeof result!=='object'||!result.action)return;
  setDialog(undefined);
  switch(result.action){
    case 'managed_bot_created': return;
    case 'settings': navigate('settings');return;
    case 'search': navigate('chats');setToast('Busca el chat o mensaje desde la barra de búsqueda.');return;
    case 'subscription_active': setToast('Suscripción activa. Busca el canal en tu lista de chats.');return;
    case 'request_sent': setToast('Solicitud enviada. Los administradores de Telegram deben aprobarla.');return;
    case 'story': {
      if(!result.chatId||!result.storyId)return;
      const owner=snapshot().chats.find(chat=>chat.id===result.chatId)??{id:result.chatId,title:result.title||'Historia de Telegram',preview:'',date:0,unread:0,marked:false,bot:false,type:'private',pinned:false,muted:false,archived:false,supported:true};
      navigate('chats');setMobileChat(true);showStory(owner,result.storyId);return;
    }
    case 'boost':
      if(result.chatId){navigate('chats');setMobileChat(true);openBoosts(boostTarget(result.chatId,result.title||'',result.channel===true));}
      return;
    case 'sticker': setToast('Pack de stickers «'+(result.title||'Telegram')+'» disponible en Telegram.');return;
    case 'message':
      if(result.messageId){setHighlight({id:result.messageId,chatId:result.chatId||snapshot().active});jumpPending.current=true;followLatest.current=false;}
      setToast('Mensaje enlazado abierto en su conversación.');
      break;
    default: setToast(result.title?'Abriendo '+result.title+'…':'Enlace de Telegram abierto.');
  }
  navigate('chats');setMobileChat(true);
}
