 function sendCommand(message:Message,command:string){const text=command.trim();if(!text)return;if(!state.ready||!state.canSend||state.sending){void run('clipboard.copy',{text});setToast('Comando copiado: este chat no permite enviar mensajes.');return;}const perform=()=>void run<boolean>('send.text',{text,reply:active&&active.type==='group'?message.id:'0',acknowledge:state.uncertain,silent}).then(sent=>{if(sent){followLatest.current=true;if(!state.history.latest)void run('history.refresh');}});if(state.uncertain)confirm('Comprueba el envío anterior','Podría haber llegado aunque venciera la espera. Revisa el historial para evitar duplicados.','Enviar de todas formas',perform);else perform();}
  function cancelDraftTimer(key:string){
    clearTimeout(draftTimers.current.get(key));draftTimers.current.delete(key);
  }
  function persistDraft(scope:ConversationScope,value:string,entities:TextEntity[]){
    const key=conversationKey(scope);
    cancelDraftTimer(key);
    draftTimers.current.set(key,setTimeout(()=>{
      draftTimers.current.delete(key);
      if(snapshot().selfId===scope.accountId)void request('draft.set',{...scope,text:value,entities}).catch(()=>{});
    },900));
  }
  function changeDraft(value:string,caret?:number,entities=editDraftEmojis(draft,value,draftEntities,caret)){
    setDraft(value);
    setDraftEntities(entities);
    drafts.current.set(draftKey,value);
    draftEmojis.current.set(draftKey,entities);
    if(!native||!state.ready||!active)return;
    void run('typing',{active:!!value.trim()});
    if(active.type!=='secret')persistDraft(draftScope,value,entities);
  }

  function insertExpression(emoji:string,customId?:string){
    const start=field.current?.selectionStart??draft.length;
    const end=field.current?.selectionEnd??draft.length;
    const next=draft.slice(0,start)+emoji+draft.slice(end);
    if(next.length>4096){setToast('Alcanzaste el límite del mensaje.');return;}
    const entities=replaceDraftEmojis(draftEntities,start,end,emoji.length,customId);
    if(entities.length>100){setToast('Telegram admite hasta 100 elementos de formato por mensaje.');return;}
    changeDraft(next,undefined,entities);
    // Keep the mobile keyboard closed while choosing another expression.
    requestAnimationFrame(()=>field.current?.setSelectionRange(start+emoji.length,start+emoji.length));
  }


