   function createCommunity(kind:'supergroup'|'forum'|'channel'){const label=kind==='channel'?'canal':kind==='forum'?'foro':'supergrupo';const finish=(title:string,description:string,result:{id:string})=>{void run('chat.open',{id:result.id}).then(opened=>{if(opened!==undefined){navigate('chats');setMobileChat(true);void run('chats.more');}});setDialog({title:`${label.charAt(0).toUpperCase()+label.slice(1)} creado`,body:<><p>“{title}” ya existe en Telegram{description?` con la descripción indicada`:''}. No se invitó a nadie ni se publicó contenido.</p><p className="settings-note">Puedes configurar un nombre público para compartirlo con t.me. Solo se aplica si Telegram confirma que está disponible.</p><div className="modal-actions"><button className="secondary" onClick={()=>setDialog(undefined)}>Ahora no</button><button className="primary" onClick={()=>openChatUsername(result.id,title)}>Configurar nombre público</button></div></>});};setDialog({title:`Crear ${label}`,body:<><p>Telegram creará un espacio nuevo en tu cuenta. No se invitará a nadie ni se publicarán mensajes automáticamente. {kind==='channel'?'El canal se crea privado.':'El espacio se crea privado.'} Su enlace y audiencia se gestionan después desde Telegram.</p><TextEntry label={`Nombre del ${label}`} maximum={128} action="Continuar" submit={title=>setDialog({title:`Descripción del ${label}`,body:<><p className="settings-note">Opcional. Telegram puede mostrarla en la información del chat; puedes cambiarla después.</p><TextEntry label="Descripción · vacío para omitir" maximum={255} allowEmpty multiline action="Revisar creación" submit={description=>confirm(`Crear ${label}`,`Se creará “${title.trim()}”${description.trim()?` con una descripción de ${description.trim().length} caracteres`:''} en Telegram. No se invitará a miembros automáticamente.`,'Crear',()=>{void run<{id:string}>('groups.createSuper',{title:title.trim(),description:description.trim(),kind}).then(result=>{if(result)finish(title.trim(),description.trim(),result);});})}/></>})}/></>});}
   function newChat(mode:unknown=false){const secret=mode===true;setDialog({title:secret?'Nuevo chat secreto':'Nueva conversación',body:<><p>{secret?'Crea una sesión E2EE en este dispositivo. La otra persona debe aceptar; compara después la clave por un canal de confianza.':'Abre un usuario o bot por su nombre público de Telegram.'}</p><TextEntry label="Nombre de usuario público" placeholder="@usuario" maximum={33} action={secret?'Crear chat secreto':'Abrir en Telegram'} submit={username=>void run(secret?'chat.secret':'chat.find',{username}).then(result=>{if(result!==undefined){setDialog(undefined);navigate('chats');setMobileChat(true);}})}/>{!secret&&<div className="action-list"><button className="menu-item" onClick={()=>createCommunity('supergroup')}><Users/><span>Crear supergrupo</span><ChevronRight size={15}/></button><button className="menu-item" onClick={()=>createCommunity('forum')}><MessageCircle/><span>Crear foro</span><ChevronRight size={15}/></button><button className="menu-item" onClick={()=>createCommunity('channel')}><Send/><span>Crear canal privado</span><ChevronRight size={15}/></button><button className="text-button" onClick={()=>newChat(true)}><LockKeyhole size={16}/>Crear un chat secreto</button></div>}</>});}
  function chatInfo(chat:Chat){if(desktop)return;if(chat.type!=='secret'){setDetails(!details);return;}setDialog({title:'Seguridad del chat secreto',body:<><p>Estado: {chat.secretState==='ready'?'E2EE listo':chat.secretState==='closed'?'Cerrado':'Esperando a la otra persona'}. Solo existe en los dispositivos de este chat, no en la nube de Telegram.</p><p>Compara estos 32 bytes con la otra persona por un canal de confianza. Si no coinciden, no compartas información sensible.</p><pre className="secret-fingerprint">{chat.fingerprint||'La clave todavía no está disponible.'}</pre><p>El contenido temporal aún no se abre desde esta beta. No se exporta multimedia del chat secreto.</p></>});}
  function send(scheduleAt:0|number|'online'=0,repeatPeriod=0){
    if(!draft.trim()||state.sending||!state.canSend)return;
    const formatted=parseFormatting(draft,draftEntities);
    if(formatted.entities.length>100){setToast('Telegram admite hasta 100 elementos de formato por mensaje.');return;}
    if(!formatted.text.trim()){setToast('El formato aplicado no deja texto para enviar.');return;}
    if(scheduleAt&&active?.type==='secret'){setToast('Los chats secretos no admiten mensajes programados.');return;}
    const value=draft;
    const sameConversation=()=>{
      const current=snapshot();
      return conversationKey({accountId:current.selfId,chatId:current.active,topicId:current.topic?.id||0})===draftKey;
    };
    const perform=async()=>{
      if(!sameConversation()){setToast('La conversación cambió. No se envió el mensaje.');return;}
      const scheduledDraft=draftTimers.current.has(draftKey);
      cancelDraftTimer(draftKey);
      const sent=await run<boolean>('send.text',{...draftScope,text:formatted.text,entities:formatted.entities,reply:reply?.id||'0',acknowledge:state.uncertain,silent,...(repeatPeriod?{repeatPeriod}:{}),...(scheduleAt?(scheduleAt==='online'?{schedule:'online'}:{schedule:scheduleAt}):{})});
      const current=snapshot();
      if(current.selfId!==draftScope.accountId)return;
      const local=drafts.current.get(draftKey);
      const sameDraft=local===value&&draftEmojis.current.get(draftKey)===draftEntities;
      if(!sent){
        if(scheduledDraft&&sameDraft)persistDraft(draftScope,value,draftEntities);
        return;
      }
      if(local===undefined||sameDraft){
        drafts.current.set(draftKey,'');
        draftEmojis.current.set(draftKey,[]);
        if(sameConversation()){setDraft('');setDraftEntities([]);setReply(undefined);}
      }
      if(!sameConversation())return;
      followLatest.current=true;
      if(!scheduleAt&&!current.history.latest)void run('history.refresh');
      if(scheduleAt==='online')setToast('Telegram enviará el mensaje en cuanto el destinatario se conecte.');
      else if(scheduleAt)setToast('Mensaje programado para '+new Date(scheduleAt*1000).toLocaleString('es',{dateStyle:'medium',timeStyle:'short'})+'.');
    };
    if(state.uncertain)confirm('Comprueba el envío anterior','Podría haber llegado aunque venciera la espera. Revisa el historial para evitar duplicados.','Enviar de todas formas',()=>void perform());
    else void perform();
  }
 function openSchedule(){if(!draft.trim()||state.sending||!state.canSend)return;if(active?.type==='secret'){setToast('Los chats secretos no admiten mensajes programados.');return;}setDialog({title:'Programar mensaje',body:<ScheduleDialog whenOnline={active?.type==='private'} allowRepeat={!desktop&&state.wallet?.premium===true} send={(at,repeat)=>{setDialog(undefined);void send(at,repeat);}}/>});}
 function openScheduled(chat:Chat){
   if(chat.id!==state.active){setToast('Abre la conversación para administrar sus mensajes programados.');return;}
   setDialog({title:'Mensajes programados',body:<p>Consultando en Telegram…</p>});
   void run<Message[]>('scheduled.list',{id:chat.id}).then(messages=>{
     if(!messages){loadFailed('Mensajes programados',()=>openScheduled(chat));return;}
     const refresh=()=>openScheduled(chat);
     const sendNow=(message:Message)=>confirm('Enviar ahora',`Telegram enviará este mensaje a ${chat.title} inmediatamente.`,'Enviar ahora',()=>void run<boolean>('scheduled.sendNow',{id:chat.id,messageId:message.id}).then(done=>{if(done){setToast('Telegram envió el mensaje programado.');refresh();}}));
     const reschedule=(message:Message)=>setDialog({title:'Cambiar hora de envío',body:<ScheduleDialog action="Guardar nueva hora" whenOnline={chat.type==='private'} send={at=>{setDialog(undefined);void run<boolean>('scheduled.reschedule',at==='online'?{id:chat.id,messageId:message.id,online:true}:{id:chat.id,messageId:message.id,at}).then(done=>{if(done){setToast(at==='online'?'Se enviará cuando el destinatario se conecte.':'Hora de envío actualizada.');refresh();}});}}/>});
     const remove=(message:Message)=>confirm('Eliminar mensaje programado','Se eliminará de los mensajes programados de Telegram. No se enviará.','Eliminar',()=>void run<boolean>('scheduled.delete',{id:chat.id,messageId:message.id}).then(done=>{if(done){setToast('Mensaje programado eliminado.');refresh();}}),true);
     setDialog({title:`Programados · ${chat.title}`,body:messages.length?<div className="action-list">{messages.map(message=><div className="session-item" key={message.id}><strong>{message.text.slice(0,160)||'Contenido multimedia'}</strong><small>{message.scheduledAt?new Date(message.scheduledAt*1000).toLocaleString('es'):message.scheduledOnline?'Cuando se conecte':'Sin fecha'}</small>{message.scheduledRepeat&&<small>{scheduleRepeats.find(([period])=>period===message.repeatPeriod)?.[1]||'Recurrente'} · cambia su hora en Telegram</small>}<div className="scheduled-actions">{!message.scheduledRepeat&&<><button className="text-button" onClick={()=>sendNow(message)}>Enviar ahora</button><button className="text-button" onClick={()=>reschedule(message)}>Cambiar hora</button></>}<button className="text-button danger-text" onClick={()=>remove(message)}>Eliminar</button></div></div>)}<p className="settings-note">Acciones reales de Telegram. Los álbumes cambian de hora como grupo.</p></div>:<p className="settings-note">No hay mensajes programados en esta conversación.</p>});
   });
 }
