    const presetRows=THEME_PRESETS.map(item=>{const palette=resolvePreset(item);return <button type="button" className={`menu-item ${current===item.id?'selected':''}`} key={item.id} onClick={()=>choose(item.id)}><span className="theme-preset-swatch" style={{background:palette.canvas,borderColor:palette.accent}}><i style={{background:palette.accent}}/><i style={{background:palette.outgoing}}/></span><span>{item.name}</span>{current===item.id?<Check size={16}/>:<span className="theme-preset-scheme">{item.scheme==='dark'?'Oscuro':'Claro'}</span>}</button>;});
    const savedRows=(state.appearance.customThemes??[]).map(item=><button type="button" className={`menu-item ${current===item.id?'selected':''}`} key={item.id} onClick={()=>choose(item.id)}><span className="theme-preset-swatch" style={{background:item.palette.canvas,borderColor:item.palette.accent}}><i style={{background:item.palette.accent}}/><i style={{background:item.palette.outgoing}}/></span><span>{item.name}</span>{current===item.id&&<Check size={16}/>}</button>);
    setDialog({title:`Tema de “${chat.title}”`,body:<><p className="settings-note">Los colores y el fondo de esta conversación se guardan en este dispositivo.</p><WallpaperSettings key={chat.id} owner={state.selfId} chat={chat.id}/><div className="action-list"><button type="button" className={`menu-item ${current?'':'selected'}`} onClick={()=>choose('')}><span>Tema global</span>{!current&&<Check size={16}/>}</button>{presetRows}{savedRows}</div></>});
