  function chatMenu(chat:Chat){if(desktop){const act=(method:string,value:boolean)=>{void run(method,{id:chat.id,value});setDialog(undefined);};setDialog({title:chat.title,body:<div className="action-list"><MenuItem icon={<Moon/>} label="Tema de este chat" onClick={()=>openChatTheme(chat)}/><MenuItem icon={<BellOff/>} label={chat.muted?'Activar notificaciones':'Silenciar notificaciones'} onClick={()=>act('chat.mute',!chat.muted)}/>{chat.id===state.active&&<MenuItem icon={<CheckCheck/>} label="Marcar como leído" onClick={()=>{void run('chat.read');setDialog(undefined);}}/>}</div>});return;}const action=(method:string,value:boolean)=>{void run(method,{id:chat.id,value});setDialog(undefined);};setDialog({title:chat.title,body:<div className="action-list"><MenuItem icon={<Moon/>} label="Tema de este chat" onClick={()=>openChatTheme(chat)}/>{chat.id===state.active&&canConfigureBot&&<MenuItem icon={<Bot/>} label="Configurar bot" onClick={()=>openBotSetup(chat)}/>}<MenuItem icon={<Pin/>} label={chat.pinned?'Desfijar conversación':'Fijar conversación'} onClick={()=>action('chat.pin',!chat.pinned)}/>{chat.id===state.active&&<MenuItem icon={<ListChecks/>} label="Mensajes fijados" onClick={openPinned}/>}{chat.id===state.active&&chat.type!=='secret'&&<MenuItem icon={<Clock/>} label="Mensajes programados" onClick={()=>openScheduled(chat)}/>}<MenuItem icon={<BellOff/>} label={chat.muted?'Activar notificaciones':'Silenciar notificaciones'} onClick={()=>action('chat.mute',!chat.muted)}/><MenuItem icon={<Archive/>} label={chat.archived?'Desarchivar':'Archivar conversación'} onClick={()=>action('chat.archive',!chat.archived)}/><MenuItem icon={<MessageCircle/>} label={chat.marked?'Quitar marca de no leído':'Marcar como no leído'} onClick={()=>action('chat.unread',!chat.marked)}/>{chat.id===state.active&&<MenuItem icon={<CheckCheck/>} label="Marcar como leído" onClick={()=>{void run('chat.read');setDialog(undefined);}}/>}{(chat.supergroup===true||chat.type==='group'||chat.type==='channel')&&<MenuItem icon={<Link2/>} label="Crear enlace de invitación" onClick={()=>{void run('chat.invite',{id:chat.id});setDialog(undefined);}}/>}{chat.id===state.active&&canCreateSubscription&&<MenuItem icon={<Zap/>} label="Crear enlace de suscripción con Stars" onClick={()=>subscriptionInvite(chat)}/>} {chat.type==='channel'&&<><MenuItem icon={<Plus/>} label="Unirse al canal" onClick={()=>confirm(`¿Unirte a ${chat.title}?`,'Telegram registrará tu participación; las notificaciones dependen de tus ajustes.','Unirme',()=>void run('chat.join',{id:chat.id}))}/><MenuItem icon={<X/>} label="Salir del canal" onClick={()=>confirm(`¿Salir de ${chat.title}?`,'Se solicitará abandonar este canal en tu cuenta de Telegram. No se borran mensajes de otros usuarios.','Salir',()=>void run('chat.leave',{id:chat.id}),true)}/></>}</div>});}
 function toggleSelected(message:Message){setSelected(previous=>{const next=new Set(previous);if(next.has(message.id))next.delete(message.id);else next.add(message.id);return next;});}
 function bubbleSwipeStart(event:TouchEvent){const touch=event.touches[0];if(touch)swipe.current={x:touch.clientX,y:touch.clientY};}
 function bubbleSwipeEnd(message:Message,event:TouchEvent){
   const start=swipe.current;swipe.current=undefined;
   if(!start||selected.size>0||message.status==='pending'||message.status==='failed')return;
   const touch=event.changedTouches[0];if(!touch)return;
   const dx=touch.clientX-start.x,dy=touch.clientY-start.y;
   if(Math.abs(dx)<72||Math.abs(dx)<Math.abs(dy)*1.8)return;
   const action=dx>0?state.appearance.gestures?.right||'none':state.appearance.gestures?.left||'none';
   if(action==='none')return;
   void bubbleGesture(message,action);
 }
 async function bubbleGesture(message:Message,action:string){
   if(action==='reply'){setReply(message);field.current?.focus();return;}
   if(action==='copy'){void run('message.copy',{id:message.id}).then(done=>{if(done)setToast('Texto copiado.');});return;}
   if(action==='select'){toggleSelected(message);return;}
   if(action==='forward'){
     const props=await run<Properties>('message.properties',{id:message.id});
     if(!props?.forward){setToast('Telegram no permite reenviar este mensaje.');return;}
     setDialog({title:'Reenviar mensaje',body:<ForwardDialog chats={state.chats.filter(chat=>chat.supported)} ids={[message.id]} single={message} copyable={props.copyContent} run={run} close={()=>setDialog(undefined)} done={()=>{setDialog(undefined);setToast('Mensaje reenviado.');}}/>});
   }
 }
