 function wrapFormat(open:string,close=open){const area=field.current;if(!area)return;const start=area.selectionStart??draft.length,end=area.selectionEnd??draft.length,selected=draft.slice(start,end)||'texto';const opened=replaceDraftEmojis(draftEntities,start,start,open.length);const closeAt=start+open.length+selected.length;const entities=replaceDraftEmojis(opened,closeAt,closeAt,close.length);changeDraft(draft.slice(0,start)+open+selected+close+draft.slice(end),undefined,entities);requestAnimationFrame(()=>{area.focus();area.setSelectionRange(start+open.length,start+open.length+selected.length);});}
