  return <div className="paid-reaction-picker"><p className="settings-note">La reacción usa Stars de tu saldo de Telegram. WRGram no procesa el cobro; Telegram pedirá una confirmación final antes de gastarlos.</p><div className="paid-amounts">{[1,5,10,25,50].map(value=><button type="button" className={count===value?'selected':''} key={value} onClick={()=>setCount(value)}>{value} ⭐</button>)}</div><label className="field-label">Otra cantidad<input inputMode="numeric" value={String(count)} maxLength={6} onChange={event=>{const value=Number(event.target.value.replace(/\D/g,''));setCount(Number.isFinite(value)?Math.min(100000,value):0);}}/></label><button className="primary" disabled={count<1} onClick={()=>pick(count)}>Reaccionar con {count} ⭐</button></div>;
