  const pick=()=>{if(busy||items.length>=10)return;setBusy(true);setNotice('');void run<{token:string;name:string;size:number}>('attachment.pick').then(item=>{setBusy(false);if(!item||items.some(current=>current.token===item.token))return;setItems(current=>[...current,item]);});};
